    Bug 1968848 - Remove EnigmailFuncs.getDefaultIdentity(). r=edicharry


    Would subtly break ews.
    There's not too much point setting identity here at all...
    The original intention was probably to not have nntp in the list. But who's to say you
    don't want to post public keys there if you happen to have nntp as default account.
    All it does is set the compose window default anyway.

    Differential Revision: https://phabricator.services.mozilla.com/D251479

diff --git a/mail/extensions/openpgp/content/modules/funcs.sys.mjs b/mail/extensions/openpgp/content/modules/funcs.sys.mjs
index f4e3cb872d3..8e0a7fd23ac 100644
--- a/mail/extensions/openpgp/content/modules/funcs.sys.mjs
+++ b/mail/extensions/openpgp/content/modules/funcs.sys.mjs
@@ -290,36 +290,6 @@ export var EnigmailFuncs = {
     return 0;
   },

-  /**
-   * Get the default identity of the default account.
-   *
-   * @returns {?nsIMsgIdentity}
-   */
-  getDefaultIdentity() {
-    try {
-      let ac;
-      if (MailServices.accounts.defaultAccount) {
-        ac = MailServices.accounts.defaultAccount;
-      } else {
-        for (ac of MailServices.accounts.accounts) {
-          if (
-            ac.incomingServer.type === "imap" ||
-            ac.incomingServer.type === "pop3"
-          ) {
-            break;
-          }
-        }
-      }
-
-      if (ac.defaultIdentity) {
-        return ac.defaultIdentity;
-      }
-      return ac.identities[0];
-    } catch (x) {
-      return null;
-    }
-  },
-
   /**
    * Get a mail URL from a uriSpec.
    *
